+      gboolean save_fragmented;
+      fragment_head *frag_msg = NULL;
+      tvbuff_t *next_tvb = NULL;
+      gint len_rem;
+
+      proto_tree_add_item_ret_uint64(etf_tree, hf_erldp_sequence_id, tvb, offset, 8, ENC_BIG_ENDIAN, &sequence_id);
